def count_4_neighbors(grid):
    rows, cols = len(grid), len(grid[0])
    output = []
    for r in range(rows):
        row_out = []
        for c in range(cols):
            count = 0
            for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                nr, nc = r + dr, c + dc
                if 0 <= nr < rows and 0 <= nc < cols:
                    if grid[nr][nc] == 0:  # count 0s
                        count += 1
            row_out.append(count)
        output.append(row_out)
    return output

neighbor_count = count_4_neighbors(input_grid)
print("Test: count 0 neighbors for each cell (4-neighbor count)")
for row in neighbor_count:
    print(row)

